/* Shared code following missionfunc; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x0024EEF0 (was missionfunc_0024EEF0.c). */
#include "common.h"
#include "include_asm.h"

typedef struct {
    short id;             /* 0x00 */
    char _pad02[0xE];
    unsigned short flags; /* 0x10 */
    short base;           /* 0x12 */
    short ids[8];         /* 0x14 */
    short status;         /* 0x24 */
    short sel;            /* 0x26 */
} MissionNode_0024EEF0;
extern MissionNode_0024EEF0 *mission_node_list;

// Lists the current objectives: ids (or 0x5243 when done) to out, done bits to *mask, base + sel to nums; returns the count.
int CollectMissionNodes(int *out, int *mask, int *nums, int arg3) {
    MissionNode_0024EEF0 *p = mission_node_list;
    int count = 0;
    int all = 1;

    *out = 0;
    if (mask != 0) {
        *mask = 0;
    }
    if (nums != 0) {
        *nums = -1;
    }
    if (p == 0) {
        return 0;
    }
    while (p->id != 0) {
        unsigned short f = p->flags;
        short t = p->status;

        if (t != 2 && !(f & 2)) {
            all = 0;
        }
        if (!(f & 2) && t != 0 && !((f & 1) && t == 2)) {
            out[count] = p->id;
            if (arg3 != 0) {
                out[count] = (p->status == 2) ? 0x5243 : p->ids[p->sel];
            }
            if (mask != 0 && p->status == 2) {
                *mask |= 1 << count;
            }
            if (nums != 0) {
                *nums++ = p->base + p->sel;
            }
            count++;
        }
        p++;
    }
    if (mask != 0 && all != 0) {
        *mask |= 0x80000000;
    }
    return count;
}
